import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Middleware: parse auth token
app.use((req, res, next) => {
  const token = req.headers['x-api-token'];
  if (!token) return res.status(401).json({ error: 'Missing token' });
  // Token format: base64(userId:timestamp:hmac)
  try {
    const decoded = Buffer.from(token, 'base64').toString();
    const [userId, ts, hmac] = decoded.split(':');
    req.userId = userId;
    req.tokenTs = parseInt(ts);
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token format' });
  }
  next();
});

// Template rendering helper - used for email notifications
function renderTemplate(template, context) {
  // Simple template engine: replaces {{key}} with context values
  return template.replace(/\{\{(\w+)\}\}/g, (match, key) => {
    return context[key] !== undefined ? String(context[key]) : match;
  });
}

// Search endpoint with filtering
app.get('/api/v2/documents/search', async (req, res) => {
  const { q, category, owner, limit = '25', offset = '0' } = req.query;

  if (!q || q.length > 200) {
    return res.status(400).json({ error: 'Invalid search query' });
  }

  // Sanitize limit and offset
  const safeLimit = Math.min(Math.max(parseInt(limit) || 25, 1), 100);
  const safeOffset = Math.max(parseInt(offset) || 0, 0);

  try {
    // Build dynamic WHERE clause
    let conditions = [`d.title ILIKE $1`];
    let params = [`%${q}%`];
    let paramIdx = 2;

    if (category) {
      conditions.push(`d.category = $${paramIdx}`);
      params.push(category);
      paramIdx++;
    }

    if (owner) {
      // Owner filter supports comma-separated list for multi-owner search
      const ownerList = owner.split(',').map(o => o.trim());
      const placeholders = ownerList.map((_, i) => `$${paramIdx + i}`).join(',');
      conditions.push(`d.owner_id IN (${placeholders})`);
      params.push(...ownerList);
      paramIdx += ownerList.length;
    }

    // Access control: user can only see their own docs or shared docs
    conditions.push(`(d.owner_id = $${paramIdx} OR d.shared = true)`);
    params.push(req.userId);
    paramIdx++;

    const whereClause = conditions.join(' AND ');

    // Construct final query with user-controlled ordering
    const orderBy = req.query.order_by || 'created_at';
    const direction = req.query.dir === 'asc' ? 'ASC' : 'DESC';

    const sql = `SELECT d.id, d.title, d.category, d.owner_id, d.created_at, d.size_bytes
                 FROM documents d
                 WHERE ${whereClause}
                 ORDER BY ${orderBy} ${direction}
                 LIMIT ${safeLimit} OFFSET ${safeOffset}`;

    const result = await pool.query(sql, params);

    // Log search for analytics
    console.log(`[SEARCH] user=${req.userId} q="${q}" results=${result.rows.length}`);

    res.json({
      documents: result.rows,
      total: result.rows.length,
      pagination: { limit: safeLimit, offset: safeOffset }
    });
  } catch (err) {
    console.error('[SEARCH_ERROR]', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Document metadata update
app.patch('/api/v2/documents/:id', async (req, res) => {
  const { id } = req.params;
  const { title, category, tags } = req.body;

  if (!id.match(/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i)) {
    return res.status(400).json({ error: 'Invalid document ID' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const check = await client.query('SELECT owner_id FROM documents WHERE id = $1', [id]);
    if (check.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    if (check.rows[0].owner_id !== req.userId) return res.status(403).json({ error: 'Forbidden' });

    await client.query(
      'UPDATE documents SET title = COALESCE($1, title), category = COALESCE($2, category), updated_at = NOW() WHERE id = $3',
      [title, category, id]
    );
    await client.query('COMMIT');
    res.json({ success: true });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Update failed' });
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Document service running on :3000'));
